#!/usr/bin/env node
// Generates the links Worker's path table and its Apple association file from the backend's
// link-paths.json (cmh-golang, `go generate ./...` from internal/kernel/links), the one list of
// every URL the backend hands out on https://links.seemyhealth.ai.
//
//   node workers/links/scripts/generate.mjs           write the generated files
//   node workers/links/scripts/generate.mjs --check   fail if anything has drifted
//
// The source is the backend checkout when there is one ($CMH_BACKEND_REPO, else ~/cmh-golang), and
// the copy vendored beside this Worker otherwise (CI has no backend checkout). Generating refreshes
// the vendored copy; checking fails when the two differ, when a generated file differs from what the
// source makes, and when a path in the source has no page kind in src/page-kinds.ts.
//
// Run under `node --experimental-strip-types` (Node 22) so it can read page-kinds.ts; Node 24 needs
// no flag.

import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const WORKER = join(HERE, '..');
const VENDORED = join(WORKER, 'link-paths.json');
const BACKEND = join(process.env.CMH_BACKEND_REPO ?? join(homedir(), 'cmh-golang'), 'link-paths.json');
const PATHS_TS = join(WORKER, 'src', 'generated', 'link-paths.ts');
const AASA_TS = join(WORKER, 'src', 'generated', 'apple-app-site-association.ts');

// The apps that claim the links. Prod and dev builds of the iOS app share the team.
const APPLE_APP_IDS = ['2QSN6768PN.ai.seemyhealth.app', '2QSN6768PN.ai.seemyhealth.app.dev'];
const EXPECTED_HOST = 'links.seemyhealth.ai';
const EXPECTED_SCHEMA = 1;

const check = process.argv.includes('--check');
const problems = [];

const sourcePath = existsSync(BACKEND) ? BACKEND : VENDORED;
const sourceText = readFileSync(sourcePath, 'utf8');
const source = JSON.parse(sourceText);

if (source.schemaVersion !== EXPECTED_SCHEMA) problems.push(`schemaVersion is ${source.schemaVersion}, this generator reads ${EXPECTED_SCHEMA}`);
if (source.host !== EXPECTED_HOST) problems.push(`host is ${source.host}, expected ${EXPECTED_HOST}`);

const header = (what) => `// GENERATED by workers/links/scripts/generate.mjs from link-paths.json (${what}).
// Do not edit: run \`npm run links:generate\`. \`npm run links:check\` fails when this drifts.
`;

// ---- The path table ------------------------------------------------------------------------------

const paths = source.paths.map((p) => ({
  name: p.name,
  template: p.template,
  web: p.web,
  params: p.params.map((x) => ({ name: x.name, type: x.type })),
  query: p.query.map((x) => ({ name: x.name, type: x.type })),
}));

const pathsTs = `${header('the path table')}
export const LINK_HOST = ${JSON.stringify(source.host)};

export const PARAM_TYPES = ${JSON.stringify(source.paramTypes, null, 2)} as const;

export type ParamType = keyof typeof PARAM_TYPES;

export interface LinkPathSpec {
  readonly name: string;
  readonly template: string;
  readonly web: boolean;
  readonly params: readonly { readonly name: string; readonly type: ParamType }[];
  readonly query: readonly { readonly name: string; readonly type: ParamType }[];
}

export const LINK_PATHS = ${JSON.stringify(paths, null, 2)} as const satisfies readonly LinkPathSpec[];

export type LinkPathName = (typeof LINK_PATHS)[number]['name'];
`;

// ---- The Apple association file ------------------------------------------------------------------
// Every template, each {param} as *. A query the backend names stays unclaimed by value (a component
// with no "?" matches any query), except a flag, which also gets its own component so the claim says
// what it is: /family-invitations with and without ?sent.

const components = [];
for (const p of source.paths) {
  const pattern = p.template.replace(/\{[^}]+\}/g, '*');
  for (const q of p.query) {
    if (q.type === 'flag') components.push({ '/': pattern, '?': { [q.name]: '' }, comment: `${p.name}: ${p.opens}, ${q.means}` });
  }
  components.push({ '/': pattern, comment: `${p.name}: ${p.opens}` });
}

const aasa = { applinks: { details: [{ appIDs: APPLE_APP_IDS, components }] } };

const aasaTs = `${header('the Apple association file')}
export const APPLE_APP_SITE_ASSOCIATION = ${JSON.stringify(aasa, null, 2)} as const;
`;

// ---- Write or check ------------------------------------------------------------------------------

const outputs = [
  [PATHS_TS, pathsTs],
  [AASA_TS, aasaTs],
];

if (check) {
  if (sourcePath !== VENDORED && readFileSync(VENDORED, 'utf8') !== sourceText) {
    problems.push(`${relative(process.cwd(), VENDORED)} differs from the backend's ${sourcePath}: run npm run links:generate`);
  }
  for (const [file, text] of outputs) {
    if (!existsSync(file) || readFileSync(file, 'utf8') !== text) problems.push(`${relative(process.cwd(), file)} is stale: run npm run links:generate`);
  }
} else {
  writeFileSync(VENDORED, sourceText);
  for (const [file, text] of outputs) writeFileSync(file, text);
}

// Every path has a page kind, and the table names no path the backend does not.
const { PAGE_KIND_BY_PATH } = await import(join(WORKER, 'src', 'page-kinds.ts'));
const names = new Set(source.paths.map((p) => p.name));
for (const n of names) if (!(n in PAGE_KIND_BY_PATH)) problems.push(`path "${n}" has no page kind in src/page-kinds.ts`);
for (const n of Object.keys(PAGE_KIND_BY_PATH)) if (!names.has(n)) problems.push(`src/page-kinds.ts names "${n}", which link-paths.json does not`);

if (problems.length) {
  for (const p of problems) console.error(`✗ ${p}`);
  process.exit(1);
}
console.log(`${check ? '✓ up to date' : '✓ generated'}: ${source.paths.length} paths, ${components.length} association components, every path has a page kind (source: ${sourcePath})`);
